            if (matchRate < 25) buyerNPS -= 15;
            buyerNPS = Math.round(Math.max(-10, Math.min(90, buyerNPS)));

            var providerNPS = 50;
            providerNPS -= (d.takeRate - 10) * 2;
            providerNPS += (matchRate - 30) * 0.5;
            providerNPS += d.qualityInvestment / 10000 * 5;
            if (d.competitiveResponse === 1 && period >= 5) providerNPS += 10;
            if (providerChurnPct > 15) providerNPS -= 10;
            providerNPS = Math.round(Math.max(-10, Math.min(90, providerNPS)));

            var gmvGrowth = ds.monthlyGMV > 0 ? (monthlyGMV - ds.monthlyGMV) / ds.monthlyGMV * 100 : (monthlyGMV > 0 ? 100 : 0);
            var gmvScore = Math.min(20, Math.max(0, gmvGrowth * 0.5));
            var matchScore = Math.min(25, Math.max(0, matchRate / 65 * 25));
            var npsAvg = (buyerNPS + providerNPS) / 2;
            var npsScore = Math.min(25, Math.max(0, npsAvg / 70 * 25));
            var liquidityRatio = activeBuyers > 0 ? activeProviders / activeBuyers : 0;
            var optimalRatio = 0.15;
            var ratioDeviation = Math.abs(liquidityRatio - optimalRatio);
            var ratioScore = Math.min(15, Math.max(0, 15 - ratioDeviation * 50));
            var runwayScore = Math.min(15, Math.max(0, monthsRunway / 18 * 15));
            var phi = Math.round(gmvScore + matchScore + npsScore + ratioScore + runwayScore);
            phi = Math.max(0, Math.min(100, phi));

            ds.cash = Math.round(cash);
            ds.activeProviders = activeProviders;
            ds.activeBuyers = activeBuyers;
            ds.monthlyGMV = Math.round(monthlyGMV);
            ds.matchRate = matchRate;
            ds.npsBuyer = buyerNPS;
            ds.npsProvider = providerNPS;
            ds.phi = phi;
            ds.totalRevenue += roundRevenue;
            ds.avgTransactionValue = Math.round(avgTxnValue);
            ds.providerChurnRate = Math.round(providerChurnPct * 10) / 10;
            ds.buyerRepeatRate = Math.round(Math.min(70, matchRate * 0.9) * 10) / 10;
            ds.monthsRunway = monthsRunway;
            ds.cumulativeGMV += monthlyGMV * 4;

            ds.gmvHistory.push(Math.round(monthlyGMV));
            ds.phiHistory.push(phi);
            ds.matchRateHistory.push(matchRate);
            ds.revenueHistory.push(Math.round(monthlyRevenue));
            ds.providerHistory.push(activeProviders);
            ds.buyerHistory.push(activeBuyers);

            // platform score: phi is already the 0-100 composite getPerformanceSummary reads for its final verdict, so the last round value matches exactly
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: phi });

            // FIX(v1.1.0): advance synchronously to the next round. The previous
            // setTimeout closure read state.currentPeriod AFTER the framework had
            // incremented it, so the briefing, phase label, and — most damaging —
            // the expansion/competitive decision-group visibility jumped to round
            // N+2 (e.g. Round 4 wrongly showed Round 5's groups). Guard on state
            // identity so the deep-cloned competition preview never mutates the DOM.
            if (window.mySimulation && state === window.mySimulation.state) {
                var nextPeriod = (state.currentPeriod || 1) + 1;
                if (nextPeriod <= this.ROUNDS.length) {
                    this._updateBriefing({ currentPeriod: nextPeriod });
                }
            }

            return {
                period: state.currentPeriod,
                monthlyGMV: Math.round(monthlyGMV),
                monthlyRevenue: Math.round(monthlyRevenue),
                roundProfit: Math.round(roundProfit),
                activeProviders: activeProviders,
                activeBuyers: activeBuyers,
                matchRate: matchRate,
                phi: phi,
                npsBuyer: buyerNPS,
                npsProvider: providerNPS,
                cash: Math.round(cash),
                newProviders: newProviders,
                newBuyers: newBuyers,
                providerChurn: providerChurnPct,
                monthsRunway: monthsRunway
            };
        }

