        getPerformanceSummary(history) {
            if (!history.length) return {};
            var finalState = history[history.length - 1];
            var phi = finalState.results ? finalState.results.phi : 0;
            var totalGMV = history.reduce(function(s, r) { return s + (r.results ? r.results.monthlyGMV * 4 : 0); }, 0);
            var avgMatchRate = history.reduce(function(s, r) { return s + (r.results ? r.results.matchRate : 0); }, 0) / history.length;
            var finalCash = finalState.results ? finalState.results.cash : 0;

            var performance = window.mySimulation.t('perf_structural_distress');
            if (phi >= 50) performance = window.mySimulation.t('perf_viable_vulnerable');
            if (phi >= 70) performance = window.mySimulation.t('perf_fundable_platform');
            if (phi >= 85) performance = window.mySimulation.t('perf_acquisition_target');

            var insights = [];
            if (avgMatchRate < 30) {
                insights.push(window.mySimulation.t('insight_low_match'));
            }
            if (avgMatchRate >= 45) {
                insights.push(window.mySimulation.t('insight_strong_match'));
            }
            if (finalCash < 500000) {
                insights.push(window.mySimulation.t('insight_low_cash'));
            }
            if (phi >= 70) {
                insights.push(window.mySimulation.t('insight_fundable'));
            }
            if (phi < 50) {
                insights.push(window.mySimulation.t('insight_distress'));
            }

            return {
                phi: phi,
                totalGMV: totalGMV,
                avgMatchRate: Math.round(avgMatchRate * 10) / 10,
                finalCash: finalCash,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.matchRate < 20) return window.mySimulation.t('hint_low_match');
            if (results.providerChurn > 20) return window.mySimulation.t('hint_high_churn');
            if (results.monthsRunway < 6) return window.mySimulation.t('hint_low_runway');
            if (results.phi >= 70) return window.mySimulation.t('hint_strong_phi');
            if (results.monthlyGMV === 0 && state.currentPeriod > 1) return window.mySimulation.t('hint_no_gmv');
            return null;
        }

