        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = window.mySimulation.t(round.description);

            var phaseEl = document.getElementById('phaseDisplay');
            if (phaseEl) phaseEl.textContent = window.mySimulation.t(round.phase);

            var expGroup = document.getElementById('expansionGroup');
            if (expGroup) expGroup.style.display = round.showExpansion ? 'block' : 'none';

            var compGroup = document.getElementById('competitiveGroup');
            if (compGroup) compGroup.style.display = round.showCompetitive ? 'block' : 'none';
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new PlatformBuilderAdapter(), {
            simulationType: 'platform_builder_068',
            maxPeriods: 6,
            autoSaveInterval: 30000
        });
    });

})();
